  _r("constants/difficulty-constants", "var __cjsDir=\"constants\";var _require=function(id){return window.require(id,__cjsDir);};var require=_require;var __require=_require;\n\"use strict\";\n// ===== CPU Difficulty Constants =====\nconst CPU_LEVEL_NAMES = ['不明', '盤喰いの小鬼', '反転の影', '布石を紡ぐ者', '盤面支配者', '終局を告げる者', '盤理の観測者'];\nconst CPU_LEVEL_DIALOGUES = {\n    1: {\n        win: [\n            'ふふ、これが実力差だ。',\n            'ざまぁみろ、やっぱり甘いな。',\n            '見たか、人間の限界はそこだ。',\n            'その程度で満足か？もっと来い！',\n            'へっ、期待外れだな。'\n        ],\n        lose: [\n            'くそっ…次は許さない！',\n            'うわ、強い…撤退！',\n            'ぐぬぬ…悔しい！',\n            'やられた…くそっ！',\n            'ふざけるな、もう一度！'\n        ],\n        draw: 'ふん、次は勝つ。'\n    },\n    2: {\n        win: [\n            '人間ごときが勝てると思うか？',\n            '小手調べにしては上出来すぎるな、だが甘い。',\n            'お前の一手は読めていた、次も無駄だぞ。',\n            '余裕だ、見どころはそこか。',\n            'へへ、捻り潰すのは簡単だ。'\n        ],\n        lose: [\n            'ぐぬぬ…見くびられたか！',\n            'くっ…いつか返してやる！',\n            '許せん…次は策を変える！',\n            'く、悔しい…影が薄れる…',\n            'こんなところで負ける訳には…！'\n        ],\n        draw: '互角だな、悪くない。'\n    },\n    3: {\n        win: [\n            '読みが浅い、こちらの方が一枚上手だ。',\n            '計略通り、術中にはまったようだな。',\n            '面白い…だが力が足りぬ。',\n            'その程度で満足するな、もっと来い。',\n            'やはり私の読みには敵わない。'\n        ],\n        lose: [\n            'くっ…布石が乱れた…',\n            'ぬう…計算が狂った！',\n            '悔しい、次は読み切ってやる！',\n            'ちっ…隙を突かれたか！',\n            'このままでは終わらん！'\n        ],\n        draw: '悪くない、また会おう。'\n    },\n    4: {\n        win: [\n            '盤面は我が庭だ、踏み外すな。',\n            '圧倒的だ、楽しませてもらったぞ。',\n            '支配者の名は伊達ではない。',\n            '一手で崩れるその脆さ、笑うしかないな。',\n            '情けは無用、次も蹂躙してやる。'\n        ],\n        lose: [\n            '面を割られた…許さん！',\n            'どうして…支配が崩れるなど！',\n            'く、屈辱だ…練り直す！',\n            '次は徹底的に仕返ししてやる！',\n            'まさかの敗北、受け入れがたし！'\n        ],\n        draw: '興味深い、引き分けもまた一興。'\n    },\n    5: {\n        win: [\n            '貴様の全てはここで潰えた。',\n            'これが頂点と凡庸の差だ。',\n            '跪け、そして学べ。',\n            '無様だ…私の前に立つ資格なし。',\n            '終焉を見届けた、これが実力だ。'\n        ],\n        lose: [\n            '……認めたくないが悔しい。',\n            'まさかの敗北、されど次は違う。',\n            'く、実力を見誤った…屈辱だ。',\n            '負けを糧にし、研鑽を積むのみ。',\n            '敗北は痛いが、次こそは必ず。'\n        ],\n        draw: '…よい試合だった。'\n    },\n    6: {\n        win: [\n            '盤理は語る、最善は唯一。',\n            '三十手先まで視えている、抵抗は無意味だ。',\n            '観測の果て、君の手は既に詰んでいる。',\n            '全局面は掌中にある、迷いはない。',\n            '決定済みの未来だ、ただ受け入れよ。'\n        ],\n        lose: [\n            'ほう…観測を上回るとは。次は修正する。',\n            '一瞬の乱数か、だが再び誤算は許さぬ。',\n            '興味深い偏差だ。次は収束させよう。',\n            '想定外…ならば分岐を削り、必勝へ向かう。',\n            'わずかな誤差だ。再計算で終わる。'\n        ],\n        draw: '観測結果は拮抗。次は差を証明しよう。'\n    }\n};\nfunction getDialogueForOutcome(level, outcome) {\n    const levelDialogue = CPU_LEVEL_DIALOGUES[level] || CPU_LEVEL_DIALOGUES[1];\n    const entry = levelDialogue[outcome];\n    if (Array.isArray(entry)) {\n        return entry[Math.floor(Math.random() * entry.length)];\n    }\n    return entry || '';\n}\nmodule.exports = { CPU_LEVEL_NAMES, CPU_LEVEL_DIALOGUES, getDialogueForOutcome };\n//# sourceMappingURL=difficulty-constants.js.map");

